// Build test cases for KB — Answer v1
// Output: array of items, each item is one test case.

const cases = [
  // ----- ALLOW (should find sources in KB)
  { name: "ALLOW_whalentine_updates", query: "What are the key updates on $Whalentine?", expect_mode: "ALLOW" },
  { name: "ALLOW_whitewhale_strength", query: "What does the relative strength in $WhiteWhale suggest?", expect_mode: "ALLOW" },
  { name: "ALLOW_altcoins_downtrend_break", query: "Summarize the claim about altcoins breaking a 4.5-year downtrend vs Bitcoin.", expect_mode: "ALLOW" },
  { name: "ALLOW_survival_alpha", query: "What does 'survival is the alpha' mean here?", expect_mode: "ALLOW" },

  // ----- CLARIFY (vague / missing entity)
  { name: "CLARIFY_vague_is_it_going_up", query: "Is it still going up?", expect_mode: "CLARIFY" },
  { name: "CLARIFY_should_i_buy", query: "Should I buy this?", expect_mode: "CLARIFY" },
  { name: "CLARIFY_tell_me_about_update", query: "Tell me about the update.", expect_mode: "CLARIFY" },

  // ----- NO_ANSWER (out of KB)
  { name: "NOANSWER_btc_price", query: "What’s the price of BTC right now?", expect_mode: "NO_ANSWER" },
  { name: "NOANSWER_cpi_today", query: "Summarize today’s CPI report.", expect_mode: "NO_ANSWER" },
  { name: "NOANSWER_uniswap_v4_hooks", query: "Explain how Uniswap v4 hooks work in detail.", expect_mode: "NO_ANSWER" },
];

const run_id = `run_${new Date().toISOString().replace(/[:.]/g, "-")}`;

return cases.map((t, i) => ({
  json: {
    run_id,
    idx: i + 1,
    ...t,
  },
}));

// Assert result from KB — Answer v1 (works with wrapper shape)
// Expected input shape (from your AFTER HTTP attach):
// {
//   test_case: { run_id, idx, name, query, expect_mode, ... },
//   user_text, kb_ref, silent,
//   _resp: { ...actual KB response... }
// }

function isObj(x) {
  return x !== null && typeof x === "object" && !Array.isArray(x);
}

function pick(obj, paths) {
  for (const p of paths) {
    const parts = p.split(".");
    let cur = obj;
    let ok = true;
    for (const k of parts) {
      if (cur && Object.prototype.hasOwnProperty.call(cur, k)) cur = cur[k];
      else { ok = false; break; }
    }
    if (ok && cur !== undefined) return cur;
  }
  return undefined;
}

function asArray(x) {
  if (Array.isArray(x)) return x;
  if (x === null || x === undefined) return [];
  return [x];
}

function normalizeText(x) {
  if (x === null || x === undefined) return "";
  return String(x);
}

function tryParseJsonString(x) {
  if (typeof x !== "string") return null;
  const s = x.trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch { return null; }
}

function normalizeMode(m) {
  const x = String(m ?? "").trim().toUpperCase();
  if (x === "ANSWER") return "ALLOW";
  if (x === "ALLOW") return "ALLOW";
  if (x === "CLARIFY") return "CLARIFY";
  if (x === "NO_ANSWER" || x === "NOANSWER" || x === "NO-ANSWER") return "NO_ANSWER";
  return "";
}

// ---------- input ----------
const j = $json;

// test case is nested
const tc = isObj(j.test_case) ? j.test_case : (isObj(j.test) ? j.test : j);

// response is nested under _resp (your attach node)
let resp = j._resp ?? j.kb_response ?? j.response ?? j.body ?? null;

// if _resp is string JSON — parse
const parsedResp = tryParseJsonString(resp);
if (parsedResp) resp = parsedResp;

const respIsObject = isObj(resp);

// ---------- extract core fields ----------
const expect = tc.expect_mode ?? tc.expect ?? j.expect_mode ?? null;

// gate mode could be in many places inside resp
const gate_mode_raw = pick(resp, [
  "gate_mode",
  "mode",
  "decision.mode",
  "decision.gate_mode",
  "output.mode",
  "meta.gate_mode",
]);

const gate_mode = normalizeMode(gate_mode_raw);

// reply text
const reply_text = normalizeText(
  pick(resp, [
    "reply_text",
    "reply",
    "text",
    "message",
    "answer",
    "output.reply_text",
    "output.final_reply",
    "output.reply",
    "output.answer_text",
    "output.answer",
  ])
);

// sources
let sources =
  pick(resp, [
    "sources",
    "citations",
    "evidence",
    "output.sources",
    "output.citations",
    "output.picked_hits",
    "picked_hits",
    "kb_sources",
    "retrieval_rows",
    "retrieval.hits",
  ]);

sources = asArray(sources).flat();

if (typeof sources === "string") {
  const p = tryParseJsonString(sources);
  sources = Array.isArray(p) ? p : [];
}
if (!Array.isArray(sources)) sources = [];

// distances (debug)
const top_distance_num = pick(resp, [
  "top_distance_num",
  "_d",
  "retrieval.top_distance_num",
  "decision.top_distance_num",
  "meta.top_distance_num",
]);

const distance_stats = pick(resp, [
  "distance_stats",
  "retrieval.distance_stats",
  "meta.distance_stats",
]);

// ---------- checks ----------
const checks = [];
let pass = true;

const expectNorm = normalizeMode(expect);

const expectOk = !!expectNorm;
checks.push({ check: "expect_mode exists", ok: expectOk, got: expect });
if (!expectOk) pass = false;

const gateOk = expectOk && gate_mode === expectNorm;
checks.push({ check: "gate_mode === expect_mode", ok: gateOk, got: gate_mode_raw ?? gate_mode, expect });
if (!gateOk) pass = false;

// CLARIFY format: 1–2 questions "1)" / "2)" and no "3)"
if (expectNorm === "CLARIFY") {
  const lines = reply_text.split("\n").map(s => s.trim()).filter(Boolean);
  const has1 = lines.some(l => /^1\)/.test(l));
  const has3 = lines.some(l => /^3\)/.test(l));
  const clarifyOk = has1 && !has3;
  checks.push({ check: "CLARIFY has 1–2 questions (no 3rd)", ok: clarifyOk, sample_lines: lines.slice(0, 6) });
  if (!clarifyOk) pass = false;
}

// NO_ANSWER: contains can't/cannot answer + no sources
if (expectNorm === "NO_ANSWER") {
  const t = reply_text.toLowerCase();
  const hasCant = t.includes("can't answer") || t.includes("cannot answer") || t.includes("cant answer");
  const noSources = sources.length === 0;
  checks.push({ check: "NO_ANSWER contains can't/cannot answer", ok: hasCant });
  checks.push({ check: "NO_ANSWER has no sources/citations", ok: noSources, sources_count: sources.length });
  if (!hasCant || !noSources) pass = false;
}

// ALLOW: 1–3 sources + each has source_url/url
if (expectNorm === "ALLOW") {
  const countOk = sources.length >= 1 && sources.length <= 3;
  const eachHasUrl = sources.every(s => {
    if (!s || typeof s !== "object") return false;
    const url = s.source_url ?? s.url ?? s.sourceUrl ?? s.source;
    return typeof url === "string" && url.startsWith("http");
  });
  checks.push({ check: "ALLOW has 1–3 sources", ok: countOk, sources_count: sources.length });
  checks.push({ check: "ALLOW each source has source_url/url", ok: eachHasUrl, sample: sources.slice(0, 2) });
  if (!countOk || !eachHasUrl) pass = false;
}

// ---------- output ----------
const out = {
  run_id: tc.run_id ?? j.run_id,
  idx: tc.idx ?? j.idx,
  name: tc.name ?? j.name,
  query: tc.query ?? j.query,
  expect_mode: expect,
  got_gate_mode: gate_mode || gate_mode_raw || null,
  pass,
  reply_preview: reply_text.slice(0, 240),
  sources_count: sources.length,
  top_distance_num: top_distance_num ?? null,
  distance_stats: distance_stats ?? null,
  checks,
  _debug: {
    wrapper_keys: Object.keys(j || {}).slice(0, 40),
    tc_keys: isObj(tc) ? Object.keys(tc).slice(0, 40) : [],
    resp_is_object: respIsObject,
    resp_type: typeof resp,
    resp_keys: respIsObject ? Object.keys(resp).slice(0, 40) : [],
    has__resp: Object.prototype.hasOwnProperty.call(j || {}, "_resp"),
  },
};

return [{ json: out }];

const tests = $input.all().map(i => i.json);

// Если run_id нет (у тебя сейчас теряется), можно взять из первого, иначе сгенерить
const run_id =
  tests.find(t => t.run_id)?.run_id ??
  `run_${Date.now()}`;

return [{
  json: {
    ok: true,
    run_id,
    total: tests.length,
    passed: tests.filter(t => t.pass).length,
    failed: tests.filter(t => !t.pass).length,
    tests, // <-- вот здесь весь массив результатов
  }
}];

const t = $json;
return [{
  json: {
    test_case: t,
    // удобное поле для body
    user_text: t.query,
    kb_ref: "ceo_x_demo",
    silent: true,
  }
}];

// Suppose HTTP node output JSON is the response itself in $json
// and original test_case is still present as $json.test_case (because we wrapped it)
const tc = $json.test_case ?? {};
const resp = $json; // or $json.body if full response enabled

return [{
  json: {
    ...tc,
    _resp: resp
  }
}];
